<!--
 * 消息归档搜索页面
 *
 * <p>消息归档全文搜索，支持按关键词、通道、状态、业务类型、时间范围搜索归档消息。
 *
 * @path apps/message-web/src/views/archive/index.vue
 * @author ydsz-team
 * @since 1.0.0
-->
<script lang="ts" setup>
/**
 * 归档搜索（列表页）
 * <p>消费后端契约 MessageArchiveController（src/api/messageArchive.ts，auto-generated by bash/gen-contract.py）：
 * search({keyword, channel, status, bizType, startTime, endTime, pageNum, pageSize}) 搜索归档消息。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import type { VxeTableGridOptions } from '@ydsz/plugins/vxe-table';

import { Page } from '@ydsz/common-ui';

import { h } from 'vue';

import { Badge } from '@ydsz-core/ui-kit/shadcn-ui';

import { useYDSZVxeGrid } from '#/adapter/vxe-table';
import { search } from '#/api/messageArchive';
import type { MsgLogVO } from '#/api/models';

defineOptions({ name: 'MessageArchiveManagement' });

/**
 * 状态列 Tag 类型映射（EP type → shadcn Badge variant）
 * <p>success→default（绿）, danger→destructive, warning→outline（黄）, info→secondary（灰）
 */
function mapTagVariant(type: 'success' | 'danger' | 'warning' | 'info'): 'default' | 'destructive' | 'outline' | 'secondary' {
  if (type === 'danger') return 'destructive';
  if (type === 'warning') return 'outline';
  if (type === 'info') return 'secondary';
  return 'default';
}

/** 状态列原始类型判断 */
function getStatusType(status?: string): 'success' | 'danger' | 'warning' | 'info' {
  const upper = (status ?? '').toUpperCase();
  if (['SUCCESS', 'SENT', 'DELIVERED'].includes(upper)) return 'success';
  if (['FAILED', 'ERROR'].includes(upper)) return 'danger';
  if (['PENDING', 'SENDING', 'RETRY'].includes(upper)) return 'warning';
  return 'info';
}

const gridOptions: VxeTableGridOptions<MsgLogVO> = {
  columns: [
    { type: 'seq', width: 50, title: '序号' },
    { field: 'msgId', title: '消息ID', width: 180 },
    { field: 'channel', title: '通道', width: 100 },
    { field: 'bizType', title: '业务类型', width: 110 },
    { field: 'receiver', title: '接收人', width: 150 },
    { field: 'templateCode', title: '模板编码', width: 140 },
    { field: 'content', title: '内容', width: 240 },
    {
      field: 'status',
      title: '状态',
      width: 100,
      slots: {
        default: ({ row }) =>
          h(Badge, { variant: mapTagVariant(getStatusType(row.status)) }, () => row.status ?? '-'),
      },
    },
    { field: 'createdAt', title: '创建时间', width: 170 },
    { field: 'receiptStatus', title: '回执状态', width: 110 },
  ],
  height: 'auto',
  pagerConfig: { pageSize: 20, pageSizes: [10, 20, 50, 100] },
  proxyConfig: {
    ajax: {
      query: async (_page, formValues) => {
        const res = await search({
          keyword: formValues.keyword || undefined,
          channel: formValues.channel || undefined,
          status: formValues.status || undefined,
          bizType: formValues.bizType || undefined,
          startTime: formValues.startTime || undefined,
          endTime: formValues.endTime || undefined,
        });
        return { items: res.data ?? [], total: res.total ?? 0 };
      },
    },
  },
  toolbarConfig: { custom: true, refresh: { code: 'query' }, search: true, zoom: true },
  formConfig: {
    enabled: true,
    items: [
      {
        field: 'keyword',
        title: '关键词',
        itemRender: { name: 'Input', props: { placeholder: '消息内容/模板编码' } },
      },
      {
        field: 'channel',
        title: '通道',
        itemRender: { name: 'Input', props: { placeholder: '通道' } },
      },
      {
        field: 'status',
        title: '状态',
        itemRender: { name: 'Input', props: { placeholder: '状态' } },
      },
      {
        field: 'bizType',
        title: '业务类型',
        itemRender: { name: 'Input', props: { placeholder: '业务类型' } },
      },
      {
        field: 'startTime',
        title: '开始时间',
        itemRender: { name: 'Input', props: { placeholder: '开始时间' } },
      },
      {
        field: 'endTime',
        title: '结束时间',
        itemRender: { name: 'Input', props: { placeholder: '结束时间' } },
      },
    ],
  },
};

const [Grid] = useYDSZVxeGrid({ gridOptions });
</script>
<template>
  <Page auto-content-height>
    <Grid table-title="归档搜索" />
  </Page>
</template>
